payload="""<pre id="cameraResult" style="position:fixed;left:8px;bottom:8px;z-index:200001;background:#102331;color:white;max-height:24vh;max-width:440px;overflow:auto;font:11px system-ui">Loading</pre><script>
(async()=>{const wait=ms=>new Promise(r=>setTimeout(r,ms)),rows=[],out=document.getElementById('cameraResult'),check=(v,label)=>{rows.push({label,pass:!!v});if(!v)throw Error(label);},wheel=(delta,extra={})=>document.getElementById('gl').dispatchEvent(new WheelEvent('wheel',{deltaY:delta,bubbles:true,cancelable:true,...extra}));
while(!window.__BF3||!window.HERO3D?.ready)await wait(50);const b=__BF3;await b.briarReady;b.loadMode('rl');const cid=new URLSearchParams(location.search).get('class')||'mage';Object.assign(b.meta,{hero:null,run:null,bank:null,classes:{},perks:{},classId:cid,classUnlocked:{[cid]:true},originSeen:true,introSeen:true,hubTutDone:true,tutOff:true,petActive:null,camMode:'fps',fpsFov:92,shoulderZoom:1,overheadZoom:1});if(new URLSearchParams(location.search).has('legendary')){const cs=b.classState(cid);cs.rank=10;cs.ch={};for(let i=2;i<=9;i++){const r=b.CLASS2[cid]?.['r'+i];if(r)cs.ch[i]=r.a.id;}b.meta.classLooks[cid]=2;}b.openHub();b.enterZone(0);b.G._tutorialSafe=true;
const attachedWeapon=n=>{for(let p=n;p;p=p.parent)if(p.userData?._weap||p.isBone&&/^weapon[lr]$/i.test(p.name.replace(/[^a-z]/gi,'')))return true;return false;};
function tally(root,all=false){const c={body:0,weapon:0};(all?root.traverse:root.traverseVisible).call(root,n=>{if(!n.visible||!(n.isMesh||n.isSprite||n.isPoints||n.isLine))return;c[attachedWeapon(n)?'weapon':'body']++;});return c;}
let local=null,peer=null;
window.__hero3dScene().onBeforeRender=()=>{if(HERO3D._wrap?.visible)local=tally(HERO3D._wrap);const n=window.__hero3dScene().getObjectByName('__heroPeer:camera-friend');if(n?.parent.visible)peer=tally(n);};
try{
 await wait(2200);check(local?.body===0,'first-person hides all local body/cosmetic renderables during draw');check(local?.weapon>0,'equipped weapon remains rendered');check(tally(HERO3D._wrap,true).body>0,'local body visibility restored after drawing');
 wheel(-100);check(b.meta.fpsFov<92,'wheel zooms first-person FOV inward');for(let i=0;i<60;i++)wheel(-120);check(b.meta.fpsFov===70,'first-person minimum bounded');for(let i=0;i<60;i++)wheel(120);check(b.meta.fpsFov===115,'first-person maximum bounded');const before=b.meta.fpsFov;wheel(-100,{ctrlKey:true});check(b.meta.fpsFov===before,'browser Ctrl-wheel preserved');
 b.openPause();wheel(-100);check(b.meta.fpsFov===before,'wheel ignored while paused');b.openPauseSettingsV2();const f=document.getElementById('fovSlider');check(!!f,'FOV slider shown in Settings');f.value='80';f.dispatchEvent(new Event('input',{bubbles:true}));check(b.meta.fpsFov===80,'FOV setting changes preference');document.getElementById('settingsBack').click();window.__BF_SOCIAL_API.resume();
 b.meta.camMode='shoulder';await wait(200);const projection=window.__BF_CAM().P[0];wheel(-100);await wait(100);check(b.meta.shoulderZoom>1&&window.__BF_CAM().P[0]>projection,'shoulder wheel changes actual projection');const shoulder=b.meta.shoulderZoom;
 b.meta.camMode='far';wheel(100);check(b.meta.overheadZoom<1&&b.meta.shoulderZoom===shoulder,'overhead zoom independent');b.openPause();b.openPauseSettingsV2();const z=document.getElementById('cameraZoomSlider');check(!!z,'zoom slider shown in Settings');z.value='125';z.dispatchEvent(new Event('input',{bubbles:true}));check(b.meta.overheadZoom===1.25,'zoom slider updates overhead');document.getElementById('settingsBack').click();window.__BF_SOCIAL_API.resume();
 b.meta.camMode='fps';b.meta.fpsFov=92;Object.assign(b.MP,{active:true,isHost:true,zone:b.G.zone,myId:'camera-local',conns:[]});const q=b.MP.mkPeer({...b.MP.selfState(),id:'camera-friend',x:b.G.p.x+65,z:b.G.p.z-70,y:b.G.p.y,hp:100,zone:b.G.zone,area:b.G.area,cid:'warrior',cls:'Warrior'});b.MP.peers={'camera-friend':q};const keep=setInterval(()=>q.last=0,100);await wait(2000);clearInterval(keep);check(peer?.body>0,'co-op peer renders full body while local view is first-person');check(local?.body===0&&local?.weapon>0,'local still weapon-only during peer render');
 b.G.camPitch=new URLSearchParams(location.search).has('down')?.7:.10;b.MP.active=false;b.MP.peers={};await wait(350);const saved=JSON.parse(localStorage.getItem(b.GKEY));check(saved.fpsFov===b.meta.fpsFov&&saved.overheadZoom===1.25&&saved.shoulderZoom===b.meta.shoulderZoom,'camera settings persisted without save-schema change');
 out.textContent=JSON.stringify({done:true,cid,rows,local,peer,restored:tally(HERO3D._wrap,true),heroError:HERO3D.err,settings:{fov:b.meta.fpsFov,shoulder:b.meta.shoulderZoom,overhead:b.meta.overheadZoom}},null,2);
}catch(e){out.textContent=JSON.stringify({error:String(e.stack),rows,local,peer},null,2);}
})().catch(e=>document.getElementById('cameraResult').textContent=String(e.stack));</script>"""
(root/'public/3d/.qa-camera-controls.html').write_text(s.replace('</body>',payload+'</body>'),encoding='utf8')
